export function buildProcessModels(T){
 const steel=new T.MeshStandardMaterial({color:0xb6b5af,metalness:.82,roughness:.27}),ivory=new T.MeshStandardMaterial({color:0xf5f0df,roughness:.38}),red=new T.MeshStandardMaterial({color:0xa41017,metalness:.45,roughness:.27}),dark=new T.MeshStandardMaterial({color:0x515b5b,metalness:.6,roughness:.36}),oil=new T.MeshPhysicalMaterial({color:0xce921d,metalness:.18,roughness:.16,clearcoat:1}),glass=new T.MeshPhysicalMaterial({color:0xd9e4e2,transparent:true,opacity:.22,roughness:.09,metalness:.05,side:T.DoubleSide,depthWrite:false});
 const models=Array.from({length:4},()=>new T.Group()),bottles=[],drops=[];let paddle,blendLiquid,storageLiquid,labLiquid;
 function cylinder(parent,r,h,x,y,z,material=steel){const m=new T.Mesh(new T.CylinderGeometry(r,r,h,48),material);m.position.set(x,y,z);parent.add(m);return m}
 function box(parent,w,h,d,x,y,z,material=steel){const m=new T.Mesh(new T.BoxGeometry(w,h,d),material);m.position.set(x,y,z);parent.add(m);return m}
 function pipe(parent,points,material=steel,r=.045){const curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p)));const m=new T.Mesh(new T.TubeGeometry(curve,40,r,8,false),material);parent.add(m);return curve}
 function vessel(parent,x,r,height,cutaway=false){cylinder(parent,r,height,x,height/2,0,cutaway?glass:steel);cylinder(parent,r+.025,.06,x,.03,0);cylinder(parent,r+.025,.08,x,height+.025,0,ivory);for(const z of [-.28,.28])box(parent,.1,.2,.1,x,.1,z,dark)}
 vessel(models[0],-.7,.5,1.55);vessel(models[0],.78,.35,.9,true);storageLiquid=cylinder(models[0],.31,.65,.78,.42,0,oil);pipe(models[0],[[-.7,1.7,0],[-.7,1.95,0],[.8,1.95,0],[.8,1.04,0]],red);
 for(let i=0;i<4;i++){const drop=new T.Mesh(new T.SphereGeometry(.045,12,8),oil);models[0].add(drop);drops.push(drop)}
 vessel(models[1],0,.7,1.45,true);blendLiquid=cylinder(models[1],.66,.85,0,.47,0,oil);cylinder(models[1],.025,1.55,0,1.06,0,dark);box(models[1],.36,.35,.34,0,1.82,0,red);paddle=new T.Group();paddle.position.y=.68;models[1].add(paddle);box(paddle,1.05,.09,.13,0,0,0,steel);box(paddle,.13,.09,1.05,0,0,0,steel);pipe(models[1],[[.7,.34,0],[1.05,.34,0],[1.05,.12,0]],red);const whirl=new T.Mesh(new T.TorusGeometry(.46,.018,8,64,Math.PI*1.7),ivory);whirl.rotation.x=Math.PI/2;whirl.position.y=.91;paddle.add(whirl);
 const labGlass=new T.MeshPhysicalMaterial({color:0xf2f7f4,metalness:0,roughness:.045,transmission:.82,thickness:.045,ior:1.47,transparent:true,opacity:.95,side:T.DoubleSide});
 const sampleOil=new T.MeshPhysicalMaterial({color:0xd3a13d,metalness:.06,roughness:.09,transmission:.26,thickness:.2,ior:1.46,clearcoat:1});
 const profile=[[0,.025],[.39,.025],[.48,.08],[.48,.92],[.47,.95],[.445,.95],[.445,.12],[.39,.07],[0,.07]];
 const beaker=new T.Mesh(new T.LatheGeometry(profile.map(([r,y])=>new T.Vector2(r,y)),96),labGlass);models[2].add(beaker);
 const rimLip=new T.Mesh(new T.TorusGeometry(.46,.018,10,96),labGlass);rimLip.rotation.x=Math.PI/2;rimLip.position.y=.945;models[2].add(rimLip);
 labLiquid=cylinder(models[2],.432,.34,0,.245,0,sampleOil);
 const meniscus=new T.Mesh(new T.TorusGeometry(.421,.012,8,80),sampleOil);meniscus.rotation.x=Math.PI/2;meniscus.position.y=.413;models[2].add(meniscus);
 const etch=new T.MeshBasicMaterial({color:0x72786e,transparent:true,opacity:.5});
 for(let i=0;i<6;i++){const tick=new T.Mesh(new T.BoxGeometry(i%2?.065:.11,.006,.004),etch);tick.position.set(-.17,.22+i*.1,.437);models[2].add(tick)}
 cylinder(models[2],.78,.07,0,-.02,0,ivory);cylinder(models[2],.79,.025,0,-.065,0,steel);
 cylinder(models[2],.025,1.9,-.72,.9,-.22,steel);box(models[2],.7,.04,.04,-.37,1.64,-.22,steel);
 const pipette=new T.Group();pipette.position.set(.1,1.6,.05);pipette.rotation.z=-.08;models[2].add(pipette);
 cylinder(pipette,.07,.4,0,.12,0,red);cylinder(pipette,.076,.05,0,.34,0,steel);cylinder(pipette,.047,.15,0,.42,0,ivory);cylinder(pipette,.057,.035,0,.51,0,red);
 cylinder(pipette,.025,.4,0,-.28,0,labGlass);const tip=new T.Mesh(new T.ConeGeometry(.028,.14,32),steel);tip.rotation.z=Math.PI;tip.position.y=-.53;pipette.add(tip);
 const labDrop=new T.Mesh(new T.SphereGeometry(.045,24,16),sampleOil);models[2].add(labDrop);
 const ripples=[];for(let i=0;i<2;i++){const material=new T.MeshBasicMaterial({color:0xf3d595,transparent:true,opacity:.3,depthWrite:false});const ring=new T.Mesh(new T.TorusGeometry(.12,.005,6,64),material);ring.rotation.x=Math.PI/2;ring.position.set(.06,.417,.05);models[2].add(ring);ripples.push(ring)}
 const sampleTray=new T.Group();sampleTray.position.set(.9,0,-.3);models[2].add(sampleTray);cylinder(sampleTray,.11,.25,0,.13,0,labGlass);cylinder(sampleTray,.085,.12,0,.08,0,sampleOil);
 box(models[3],2.8,.14,.72,0,.18,0,dark);for(let i=0;i<9;i++){const roller=cylinder(models[3],.07,.75,-1.25+i*.31,.23,0,steel);roller.rotation.x=Math.PI/2}for(const x of [-1.1,1.1])box(models[3],.12,.25,.6,x,.04,0,steel);
 pipe(models[3],[[0,.96,-.42],[0,1.5,-.42],[0,1.5,0],[0,1.12,0]],steel,.05);box(models[3],.27,.28,.25,0,1.56,-.42,red);const stream=cylinder(models[3],.018,.28,0,.93,0,oil);
 for(let i=0;i<4;i++){const b=new T.Group();models[3].add(b);box(b,.34,.5,.22,0,.52,0,glass);const fluid=box(b,.29,.42,.18,0,.5,0,oil);cylinder(b,.085,.14,0,.84,0,ivory);const cap=cylinder(b,.1,.065,0,.93,0,red);const label=box(b,.22,.22,.008,0,.53,.115,red);bottles.push({group:b,cap,label,fluid})}
 models.forEach(m=>m.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}}));
 return {models,update(t,stage){const time=t*.001;models.forEach((m,i)=>m.visible=i===stage);paddle.rotation.y=time*1.8;storageLiquid.scale.y=.35+((time*.17)%1)*.65;storageLiquid.position.y=.1+.325*storageLiquid.scale.y;blendLiquid.scale.y=.97+Math.sin(time*2)*.025;drops.forEach((drop,i)=>{drop.position.set(.8,1.8-((time*.55+i*.25)%1)*.83,0);drop.visible=stage===0});const dropPhase=(time*.65)%1;labDrop.position.set(.058,.99-dropPhase*dropPhase*.57,.05);labDrop.scale.set(.8,1.25,.8);labDrop.visible=dropPhase<.97;labLiquid.scale.y=1;pipette.position.y=1.6+Math.sin(time*.65)*.008;ripples.forEach((ring,i)=>{const q=(dropPhase+i*.5)%1;ring.scale.setScalar(.4+q*2.2);ring.material.opacity=(1-q)*.28});bottles.forEach(({group,cap,label,fluid},i)=>{const x=((time*.38+i*.75)%3)-1.5;group.position.x=x;cap.visible=x>.28;const fill=Math.max(.07,Math.min(1,(x+.35)/.7));fluid.scale.y=fill;fluid.position.y=.3+fill*.21;label.visible=x>.28});stream.visible=Math.sin(time*2)>-.35;}};
}
export async function mountFactoryDetail(canvas){
 const T=await import('./three.module.js');const renderer=new T.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
 const envCanvas=document.createElement('canvas');envCanvas.width=512;envCanvas.height=256;const c=envCanvas.getContext('2d');c.fillStyle='#9b9a91';c.fillRect(0,0,512,256);c.fillStyle='#fffdf4';c.fillRect(30,0,90,256);c.fillRect(350,20,65,210);c.fillStyle='#5e6667';c.fillRect(220,90,60,160);const env=new T.CanvasTexture(envCanvas);env.mapping=T.EquirectangularReflectionMapping;const pm=new T.PMREMGenerator(renderer);const envTarget=pm.fromEquirectangular(env);pm.dispose();env.dispose();
 const scene=new T.Scene();scene.environment=envTarget.texture;const camera=new T.OrthographicCamera(-2.1,2.1,1.7,-1.7,.1,30);camera.position.set(4,3.2,5);camera.lookAt(0,.82,0);
 scene.add(new T.HemisphereLight(0xffffff,0xc0b49a,2.2));const key=new T.DirectionalLight(0xffffff,3.1);key.position.set(-3,6,4);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-3;key.shadow.camera.right=3;key.shadow.camera.top=3;key.shadow.camera.bottom=-3;key.shadow.bias=-.001;scene.add(key);const rim=new T.DirectionalLight(0xf6dba8,1.5);rim.position.set(4,3,-3);scene.add(rim);
 const floor=new T.Mesh(new T.PlaneGeometry(10,10),new T.ShadowMaterial({opacity:.075}));floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;scene.add(floor);const {models,update}=buildProcessModels(T);models.forEach(m=>scene.add(m));let w=0,h=0;
 return(t,stage)=>{const width=canvas.clientWidth,height=canvas.clientHeight;if(!width||!height)return;if(width!==w||height!==h){w=width;h=height;renderer.setSize(w,h,false);const aspect=w/h;camera.left=-1.7*aspect;camera.right=1.7*aspect;camera.updateProjectionMatrix()}update(t,stage);renderer.render(scene,camera)};
}
